window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["expo"]={html:"<div class=\"own-expo\" id=\"expo-top\">\n  <!-- ── TOP NAV ──────────────────────────────────────────────────────── -->\n  <header class=\"nav\" id=\"expoNav\">\n    <div class=\"nav-in\">\n      <a class=\"wordmark\" href=\"#expo-top\" aria-label=\"Northwind home\">\n        <span class=\"mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M3 16.5 9 9l4 4.5L21 5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M3 21h18\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" opacity=\".35\"/></svg>\n        </span>\n        Northwind\n      </a>\n      <nav class=\"nav-links\" aria-label=\"Primary\">\n        <a href=\"#expo-tools\">Tools</a>\n        <a href=\"#expo-workflows\">Workflows</a>\n        <a href=\"#expo-eas\">EAS</a>\n        <a href=\"#expo-pricing\">Pricing</a>\n        <a href=\"#expo-integrations\">Docs</a>\n        <a href=\"#expo-customers\">Showcase</a>\n      </nav>\n      <div class=\"nav-right\">\n        <a class=\"nav-signin\" href=\"#\">Sign in</a>\n        <a class=\"btn btn-primary\" href=\"#expo-cta\">Get started</a>\n        <button class=\"nav-burger\" type=\"button\" aria-label=\"Open menu\" aria-expanded=\"false\" data-burger>\n          <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\"/></svg>\n        </button>\n      </div>\n    </div>\n  </header>\n\n  <div class=\"clip\">\n    <!-- ── HERO + DEVICE MOCKUP ───────────────────────────────────────── -->\n    <section class=\"hero\" aria-labelledby=\"expoHeroH\">\n      <div class=\"hero-wash\" aria-hidden=\"true\"></div>\n      <div class=\"wrap hero-in\">\n        <span class=\"badge\">Operations analytics · multi-region</span>\n        <h1 id=\"expoHeroH\" class=\"hero-title\">Run every region from one operations dashboard.</h1>\n        <p class=\"hero-sub\">Northwind turns throughput, latency, and cost telemetry from every site into live dashboards your operators can act on — no spreadsheets, no overnight exports.</p>\n        <div class=\"hero-cta\">\n          <a class=\"btn btn-primary\" href=\"#expo-cta\">Start free</a>\n          <a class=\"btn btn-secondary\" href=\"#expo-tools\">See how it works</a>\n        </div>\n        <p class=\"hero-foot\">Free for one site · No credit card · <a class=\"tlink\" href=\"#expo-pricing\">Compare plans</a></p>\n\n        <div class=\"mock-stage\" aria-hidden=\"true\">\n          <div class=\"laptop\">\n            <div class=\"laptop-screen\">\n              <div class=\"dash\">\n                <div class=\"dash-bar\">\n                  <span class=\"dot red\"></span><span class=\"dot amber\"></span><span class=\"dot green\"></span>\n                  <span class=\"dash-name\">Northwind · Operations</span>\n                  <span class=\"dash-live\"><i></i>Live</span>\n                </div>\n                <div class=\"dash-body\">\n                  <aside class=\"dash-side\">\n                    <span class=\"ds on\">Overview</span>\n                    <span class=\"ds\">Regions</span>\n                    <span class=\"ds\">Throughput</span>\n                    <span class=\"ds\">Alerts</span>\n                    <span class=\"ds\">Cost</span>\n                  </aside>\n                  <div class=\"dash-main\">\n                    <div class=\"kpis\">\n                      <div class=\"kpi\"><b class=\"kpi-num\" data-count=\"18400\" data-fmt=\"k\">0</b><span>units / min</span></div>\n                      <div class=\"kpi\"><b class=\"kpi-num\" data-count=\"99\" data-suffix=\".2%\">0</b><span>on-time</span></div>\n                      <div class=\"kpi\"><b class=\"kpi-num\" data-count=\"7\">0</b><span>regions live</span></div>\n                    </div>\n                    <svg class=\"dash-chart\" viewBox=\"0 0 320 90\" preserveAspectRatio=\"none\">\n                      <defs>\n                        <linearGradient id=\"expoChartFill\" x1=\"0\" y1=\"0\" x2=\"0\" y2=\"1\">\n                          <stop offset=\"0\" stop-color=\"#a8c8e8\" stop-opacity=\".6\"/>\n                          <stop offset=\"1\" stop-color=\"#a8c8e8\" stop-opacity=\"0\"/>\n                        </linearGradient>\n                      </defs>\n                      <path fill=\"url(#expoChartFill)\" d=\"M0,64 L0,42 C30,32 50,54 80,46 C110,38 130,22 160,30 C190,38 210,16 240,24 C270,32 300,14 320,20 L320,90 L0,90 Z\"/>\n                      <path fill=\"none\" stroke=\"#171717\" stroke-width=\"2\" stroke-linecap=\"round\" d=\"M0,42 C30,32 50,54 80,46 C110,38 130,22 160,30 C190,38 210,16 240,24 C270,32 300,14 320,20\"/>\n                    </svg>\n                    <div class=\"dash-log\" id=\"expoLog\"></div>\n                  </div>\n                </div>\n              </div>\n            </div>\n            <div class=\"laptop-base\"><span class=\"laptop-notch\"></span></div>\n          </div>\n          <div class=\"phone\">\n            <div class=\"phone-notch\"></div>\n            <div class=\"phone-screen\">\n              <span class=\"ph-brand\">Northwind</span>\n              <b class=\"ph-num\">18.4k</b>\n              <span class=\"ph-cap\">units / min</span>\n              <div class=\"ph-bars\"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div>\n              <span class=\"ph-note\">APAC ahead of plan</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── WORKFLOW STEPS ─────────────────────────────────────────────── -->\n    <section class=\"sec\" id=\"expo-workflows\" aria-labelledby=\"expoWfH\">\n      <div class=\"wrap\">\n        <p class=\"eyebrow\">Workflows</p>\n        <h2 id=\"expoWfH\" class=\"sec-title\">Get every region on one dashboard</h2>\n        <p class=\"sec-lead\">Four steps from raw telemetry to an operations view your whole team trusts.</p>\n        <ol class=\"steps\">\n          <li class=\"step\">\n            <span class=\"step-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 7V4m6 3V4M7 7h10v5a5 5 0 0 1-5 5 5 5 0 0 1-5-5zM12 17v4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></span>\n            <span class=\"step-n\">01</span>\n            <h3 class=\"step-t\">Connect</h3>\n            <p class=\"step-d\">Point Northwind at your warehouses, queues, and APIs. Read-only, scoped, and live within minutes.</p>\n          </li>\n          <li class=\"step\">\n            <span class=\"step-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M4 6h16M4 12h16M4 18h10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\"/><circle cx=\"18\" cy=\"18\" r=\"2.4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg></span>\n            <span class=\"step-n\">02</span>\n            <h3 class=\"step-t\">Model</h3>\n            <p class=\"step-d\">Map regions, sites, and throughput metrics once. Northwind keeps the definitions consistent everywhere.</p>\n          </li>\n          <li class=\"step\">\n            <span class=\"step-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><path d=\"M3 13h4l2.5-6 4 12 3-8 2 2h4.5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg></span>\n            <span class=\"step-n\">03</span>\n            <h3 class=\"step-t\">Monitor</h3>\n            <p class=\"step-d\">Live dashboards, alert thresholds, and anomaly flags that surface a slipping region before the SLA does.</p>\n          </li>\n          <li class=\"step\">\n            <span class=\"step-icon\" aria-hidden=\"true\"><svg viewBox=\"0 0 24 24\"><circle cx=\"6\" cy=\"12\" r=\"2.4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><circle cx=\"18\" cy=\"6\" r=\"2.4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><circle cx=\"18\" cy=\"18\" r=\"2.4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/><path d=\"M8.2 11 15.8 7M8.2 13l7.6 4\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/></svg></span>\n            <span class=\"step-n\">04</span>\n            <h3 class=\"step-t\">Share</h3>\n            <p class=\"step-d\">Scheduled digests to Slack and email, plus read-only exec views that stay in sync automatically.</p>\n          </li>\n        </ol>\n      </div>\n    </section>\n\n    <!-- ── DARK FEATURE CARDS + CODE ──────────────────────────────────── -->\n    <section class=\"sec dark-band\" id=\"expo-tools\" aria-labelledby=\"expoToolsH\">\n      <div class=\"wrap\">\n        <p class=\"eyebrow on-dark\">Tools</p>\n        <h2 id=\"expoToolsH\" class=\"sec-title on-dark\">Instrument the whole operation</h2>\n        <p class=\"sec-lead on-dark-soft\">Query every metric with SQL you already know, then pin the answer to a dashboard.</p>\n        <div class=\"tools-grid\">\n          <div class=\"code-block\">\n            <div class=\"code-bar\"><span class=\"dot red\"></span><span class=\"dot amber\"></span><span class=\"dot green\"></span><span class=\"code-file\">throughput.sql</span></div>\n            <pre class=\"code\"><code><span class=\"c-key\">select</span> region, avg(throughput) <span class=\"c-key\">as</span> units_per_min\n<span class=\"c-key\">from</span> northwind.metrics\n<span class=\"c-key\">where</span> ts &gt; now() - <span class=\"c-key\">interval</span> <span class=\"c-str\">'24 hours'</span>\n<span class=\"c-key\">group by</span> region\n<span class=\"c-key\">order by</span> units_per_min <span class=\"c-key\">desc</span>;</code></pre>\n          </div>\n          <div class=\"tool-cards\">\n            <article class=\"card-dark\">\n              <h3 class=\"card-dark-t\">Live regional rollups</h3>\n              <p class=\"card-dark-p\">Every site reports into one model, so a region total is never a spreadsheet away.</p>\n            </article>\n            <article class=\"card-dark\">\n              <h3 class=\"card-dark-t\">Anomalies before SLAs slip</h3>\n              <p class=\"card-dark-p\">Thresholds learn each region's rhythm and page you on the deviation, not the symptom.</p>\n            </article>\n            <article class=\"card-dark\">\n              <h3 class=\"card-dark-t\">Cost per unit, always in view</h3>\n              <p class=\"card-dark-p\">Blend spend with throughput to see the true unit economics of every region.</p>\n            </article>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── IDE MOCKUP ─────────────────────────────────────────────────── -->\n    <section class=\"sec\" id=\"expo-eas\" aria-labelledby=\"expoEasH\">\n      <div class=\"wrap eas-in\">\n        <div class=\"eas-copy\">\n          <p class=\"eyebrow\">EAS · Studio</p>\n          <h2 id=\"expoEasH\" class=\"sec-title\">Model it once, reuse it everywhere</h2>\n          <p class=\"sec-lead\">Northwind Studio is a full workspace for definitions, pipelines, and saved views. Write the query, version the model, ship the dashboard.</p>\n          <a class=\"tlink tlink-lg\" href=\"#expo-integrations\">Explore the workspace →</a>\n        </div>\n        <div class=\"ide\" aria-hidden=\"true\">\n          <div class=\"ide-bar\">\n            <span class=\"dot red\"></span><span class=\"dot amber\"></span><span class=\"dot green\"></span>\n            <span class=\"ide-tab on\">model.sql</span>\n            <span class=\"ide-tab\">views.yaml</span>\n          </div>\n          <div class=\"ide-panes\">\n            <div class=\"ide-tree\">\n              <span class=\"it on\">▸ definitions</span>\n              <span class=\"it\">▸ pipelines</span>\n              <span class=\"it\">▸ alerts</span>\n              <span class=\"it\">▸ views</span>\n            </div>\n            <div class=\"ide-editor\">\n              <pre class=\"code small\"><code><span class=\"c-com\">-- region throughput, trailing 24h</span>\n<span class=\"c-key\">create view</span> region_rollup <span class=\"c-key\">as</span>\n<span class=\"c-key\">select</span>\n  region,\n  count(*) <span class=\"c-key\">as</span> events,\n  avg(throughput) <span class=\"c-key\">as</span> units_per_min\n<span class=\"c-key\">from</span> northwind.metrics\n<span class=\"c-key\">group by</span> region;</code></pre>\n            </div>\n          </div>\n          <div class=\"ide-term\">\n            <span class=\"term-line\"><span class=\"c-key\">nw</span> deploy region_rollup</span>\n            <span class=\"term-line ok\">✓ view deployed · 7 regions · 0.4s</span>\n            <span class=\"term-line\"><span class=\"c-key\">nw</span> <span class=\"caret\"></span></span>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── ECOSYSTEM TILE GRID ────────────────────────────────────────── -->\n    <section class=\"sec soft\" id=\"expo-integrations\" aria-labelledby=\"expoEcoH\">\n      <div class=\"wrap\">\n        <p class=\"eyebrow\">Docs · Integrations</p>\n        <h2 id=\"expoEcoH\" class=\"sec-title\">Works with the stack you already run</h2>\n        <p class=\"sec-lead\">Connectors for the warehouses, streams, and alerting tools operations teams rely on.</p>\n        <ul class=\"eco\">\n          <li class=\"tile\"><span class=\"tile-glyph\">ST</span><span class=\"tile-name\">Streams</span></li>\n          <li class=\"tile\"><span class=\"tile-glyph\">WH</span><span class=\"tile-name\">Warehouse</span></li>\n          <li class=\"tile\"><span class=\"tile-glyph\">QU</span><span class=\"tile-name\">Queues</span></li>\n          <li class=\"tile\"><span class=\"tile-glyph\">AL</span><span class=\"tile-name\">Alerts</span></li>\n          <li class=\"tile\"><span class=\"tile-glyph\">NB</span><span class=\"tile-name\">Notebooks</span></li>\n          <li class=\"tile\"><span class=\"tile-glyph\">BI</span><span class=\"tile-name\">BI Sync</span></li>\n          <li class=\"tile\"><span class=\"tile-glyph\">EX</span><span class=\"tile-name\">Exports</span></li>\n          <li class=\"tile\"><span class=\"tile-glyph\">HK</span><span class=\"tile-name\">Webhooks</span></li>\n        </ul>\n      </div>\n    </section>\n\n    <!-- ── PRICING ────────────────────────────────────────────────────── -->\n    <section class=\"sec\" id=\"expo-pricing\" aria-labelledby=\"expoPriceH\">\n      <div class=\"wrap\">\n        <p class=\"eyebrow\">Pricing</p>\n        <h2 id=\"expoPriceH\" class=\"sec-title\">Plans that scale with your regions</h2>\n        <p class=\"sec-lead\">Start free for one site. Move to Growth when you add a second region.</p>\n        <div class=\"tiers\">\n          <article class=\"tier\">\n            <h3 class=\"tier-name\">Starter</h3>\n            <p class=\"tier-price\"><b>$0</b><span>/ month</span></p>\n            <p class=\"tier-desc\">For a single site getting its first live view.</p>\n            <ul class=\"tier-list\">\n              <li>1 region · 3 dashboards</li>\n              <li>Daily refresh</li>\n              <li>Community support</li>\n            </ul>\n            <a class=\"btn btn-secondary tier-btn\" href=\"#expo-cta\">Start free</a>\n          </article>\n          <article class=\"tier featured\">\n            <span class=\"tier-flag\">Most popular</span>\n            <h3 class=\"tier-name\">Growth</h3>\n            <p class=\"tier-price\"><b>$49</b><span>/ month</span></p>\n            <p class=\"tier-desc\">For multi-region teams watching throughput live.</p>\n            <ul class=\"tier-list\">\n              <li>Unlimited regions · dashboards</li>\n              <li>5-minute refresh · alerts</li>\n              <li>Slack + email digests</li>\n            </ul>\n            <a class=\"btn btn-inverse tier-btn\" href=\"#expo-cta\">Start 14-day trial</a>\n          </article>\n          <article class=\"tier\">\n            <h3 class=\"tier-name\">Scale</h3>\n            <p class=\"tier-price\"><b>Custom</b></p>\n            <p class=\"tier-desc\">For global operations with strict controls.</p>\n            <ul class=\"tier-list\">\n              <li>SSO · audit log · RBAC</li>\n              <li>Private link · 99.99% SLA</li>\n              <li>Dedicated support engineer</li>\n            </ul>\n            <a class=\"btn btn-secondary tier-btn\" href=\"#expo-cta\">Talk to sales</a>\n          </article>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── TESTIMONIAL ────────────────────────────────────────────────── -->\n    <section class=\"sec soft\" id=\"expo-customers\" aria-labelledby=\"expoQuoteH\">\n      <div class=\"wrap\">\n        <p class=\"eyebrow\">Showcase</p>\n        <h2 id=\"expoQuoteH\" class=\"visually-hidden\">Customer stories</h2>\n        <figure class=\"quote\">\n          <blockquote class=\"quote-body\">“We went from seven regional spreadsheets to a single live view in a week. The first anomaly alert paid for the year — it caught a stalled line two hours before anyone noticed.”</blockquote>\n          <figcaption class=\"quote-foot\">\n            <span class=\"quote-avatar\" aria-hidden=\"true\">DO</span>\n            <span class=\"quote-meta\"><b>Dana Okafor</b><span>VP Operations · Meridian Freight (fictional)</span></span>\n          </figcaption>\n        </figure>\n      </div>\n    </section>\n\n    <!-- ── CTA BAND ───────────────────────────────────────────────────── -->\n    <section class=\"cta-band\" id=\"expo-cta\" aria-labelledby=\"expoCtaH\">\n      <div class=\"wrap cta-in\">\n        <h2 id=\"expoCtaH\" class=\"cta-title\">Bring every region into view.</h2>\n        <p class=\"cta-sub\">Set up your first dashboard in an afternoon.</p>\n        <div class=\"cta-actions\">\n          <a class=\"btn btn-primary\" href=\"#expo-top\">Get started</a>\n          <a class=\"tlink tlink-lg\" href=\"#expo-pricing\">Book a demo →</a>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── FOOTER ─────────────────────────────────────────────────────── -->\n    <footer class=\"foot\">\n      <div class=\"wrap\">\n        <div class=\"foot-top\">\n          <a class=\"wordmark foot-mark\" href=\"#expo-top\">\n            <span class=\"mark\" aria-hidden=\"true\">\n              <svg viewBox=\"0 0 24 24\"><path d=\"M3 16.5 9 9l4 4.5L21 5\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M3 21h18\" stroke=\"currentColor\" stroke-width=\"2.2\" stroke-linecap=\"round\" opacity=\".35\"/></svg>\n            </span>\n            Northwind\n          </a>\n          <p class=\"foot-tag\">Operations analytics for multi-region teams.</p>\n        </div>\n        <nav class=\"foot-cols\" aria-label=\"Footer\">\n          <div class=\"foot-col\">\n            <h3 class=\"foot-h\">Product</h3>\n            <a href=\"#expo-tools\">Tools</a>\n            <a href=\"#expo-workflows\">Workflows</a>\n            <a href=\"#expo-eas\">EAS</a>\n            <a href=\"#expo-pricing\">Pricing</a>\n          </div>\n          <div class=\"foot-col\">\n            <h3 class=\"foot-h\">Solutions</h3>\n            <a href=\"#expo-integrations\">Integrations</a>\n            <a href=\"#expo-workflows\">Operations</a>\n            <a href=\"#expo-customers\">Customers</a>\n            <a href=\"#expo-pricing\">Plans</a>\n          </div>\n          <div class=\"foot-col\">\n            <h3 class=\"foot-h\">Resources</h3>\n            <a href=\"#expo-integrations\">Docs</a>\n            <a href=\"#expo-tools\">Query library</a>\n            <a href=\"#expo-eas\">Studio guide</a>\n            <a href=\"#expo-cta\">Status</a>\n          </div>\n          <div class=\"foot-col\">\n            <h3 class=\"foot-h\">Company</h3>\n            <a href=\"#expo-customers\">About</a>\n            <a href=\"#expo-cta\">Careers</a>\n            <a href=\"#expo-cta\">Blog</a>\n            <a href=\"#expo-cta\">Contact</a>\n          </div>\n          <div class=\"foot-col\">\n            <h3 class=\"foot-h\">Legal</h3>\n            <a href=\"#expo-cta\">Privacy</a>\n            <a href=\"#expo-cta\">Terms</a>\n            <a href=\"#expo-cta\">Security</a>\n            <a href=\"#expo-cta\">DPA</a>\n          </div>\n        </nav>\n        <div class=\"foot-bar\">\n          <span>© 2026 Northwind Analytics — fictional sample for showcase.</span>\n          <span class=\"foot-bar-links\">\n            <a class=\"tlink tlink-sm\" href=\"#expo-cta\">Privacy</a>\n            <a class=\"tlink tlink-sm\" href=\"#expo-cta\">Terms</a>\n          </span>\n        </div>\n      </div>\n    </footer>\n  </div>\n</div>\n",css:"/* ══ NORTHWIND (Expo design language) — own showcase layout ═══════════════\n   Fictional operations-analytics product rendered in Expo's analysed design\n   system: pure-white canvas, sky-blue hero wash, black 8px CTA, Inter + JetBrains\n   Mono, hairline/soft-drop depth. Every selector is scoped under `.own-expo`;\n   production `vw` units are container units (`cqi`) and the responsive rules use\n   `@container frame` so the Tablet (820) and Phone (390) frames reflow like the\n   live site. Sticky nav tops at 68px to clear the 56px showcase toolbar. */\n\n.own-expo {\n  /* colors */\n  --primary: #000000;\n  --primary-active: #1a1a1a;\n  --text-link: #0d74ce;\n  --ink: #171717;\n  --body: #60646c;\n  --muted: #999999;\n  --muted-soft: #cccccc;\n  --hairline: #f0f0f3;\n  --hairline-soft: #f5f5f7;\n  --hairline-strong: #dcdee0;\n  --canvas: #ffffff;\n  --canvas-soft: #fafafa;\n  --surface-card: #ffffff;\n  --surface-strong: #f0f0f3;\n  --surface-dark: #171717;\n  --surface-dark-elevated: #1a1a1a;\n  --on-primary: #ffffff;\n  --on-dark: #ffffff;\n  --on-dark-soft: #b0b4ba;\n  --sky-light: #cfe7ff;\n  --sky-mid: #a8c8e8;\n  --accent-preview: #8145b5;\n  --semantic-success: #16a34a;\n\n  /* radii */\n  --r-xs: 4px;\n  --r-sm: 6px;\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-xl: 16px;\n  --r-xxl: 24px;\n  --r-pill: 9999px;\n\n  /* type */\n  --f-sans: 'Inter', -apple-system, system-ui, sans-serif;\n  --f-mono: 'JetBrains Mono', 'Fira Code', monospace;\n\n  /* rhythm */\n  --section: 96px;\n  --maxw: 1200px;\n  --gut: clamp(20px, 4cqi, 48px);\n  --ease: cubic-bezier(.16, 1, .3, 1);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--f-sans);\n  font-size: 16px;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n  text-align: left;\n  border-radius: 13px;\n}\n\n.own-expo *,\n.own-expo *::before,\n.own-expo *::after { box-sizing: border-box; }\n.own-expo :focus-visible { outline: 2px solid var(--ink); outline-offset: 2px; border-radius: 4px; }\n\n.own-expo .visually-hidden {\n  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;\n  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;\n}\n.own-expo .clip { overflow-x: clip; }\n.own-expo .wrap { width: 100%; max-width: var(--maxw); margin: 0 auto; padding: 0 var(--gut); }\n.own-expo .sec { padding: var(--section) 0; scroll-margin-top: 84px; }\n.own-expo .soft { background: var(--canvas-soft); }\n\n.own-expo .eyebrow {\n  font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase;\n  color: var(--body); margin: 0 0 14px;\n}\n.own-expo .eyebrow.on-dark { color: var(--on-dark-soft); }\n.own-expo .sec-title {\n  font-size: clamp(30px, 3.4cqi, 48px); font-weight: 600; line-height: 1.1;\n  letter-spacing: -1.44px; color: var(--ink); margin: 0; max-width: 20ch;\n}\n.own-expo .sec-title.on-dark { color: var(--on-dark); }\n.own-expo .sec-lead {\n  font-size: 16px; font-weight: 400; line-height: 1.5; color: var(--body);\n  margin: 16px 0 0; max-width: 60ch;\n}\n.own-expo .sec-lead.on-dark-soft { color: var(--on-dark-soft); }\n\n/* ── buttons + links ─────────────────────────────────────────────────────── */\n.own-expo .btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 40px; padding: 10px 18px; border-radius: var(--r-md);\n  font-family: var(--f-sans); font-size: 14px; font-weight: 500; line-height: 1;\n  letter-spacing: 0; cursor: pointer; text-decoration: none; white-space: nowrap;\n  transition: background-color .18s, border-color .18s, color .18s;\n}\n.own-expo .btn-primary { background: var(--primary); color: var(--on-primary); border: 1px solid var(--primary); }\n.own-expo .btn-primary:hover { background: var(--primary-active); }\n.own-expo .btn-primary:active { background: var(--primary-active); }\n.own-expo .btn-secondary {\n  background: var(--surface-card); color: var(--ink); border: 1px solid var(--hairline-strong);\n}\n.own-expo .btn-secondary:hover { border-color: var(--ink); }\n.own-expo .btn-inverse { background: var(--on-dark); color: var(--ink); border: 1px solid var(--on-dark); }\n.own-expo .btn-inverse:hover { background: #e9e9ec; }\n.own-expo .tlink {\n  color: var(--text-link); text-decoration: none; font-weight: 500;\n  border-bottom: 1px solid color-mix(in srgb, var(--text-link) 35%, transparent);\n}\n.own-expo .tlink:hover { border-bottom-color: var(--text-link); }\n.own-expo .tlink-lg { font-size: 15px; }\n.own-expo .tlink-sm { font-size: 14px; }\n.own-expo .badge {\n  display: inline-block; padding: 4px 10px; border-radius: var(--r-pill);\n  background: var(--surface-strong); color: var(--ink);\n  font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase;\n}\n\n/* ── top nav (sticky, not fixed) ─────────────────────────────────────────── */\n.own-expo .nav {\n  position: sticky; top: 68px; z-index: 30;\n  background: color-mix(in srgb, var(--canvas) 88%, transparent);\n  -webkit-backdrop-filter: saturate(1.4) blur(10px);\n  backdrop-filter: saturate(1.4) blur(10px);\n  border-bottom: 1px solid var(--hairline);\n}\n.own-expo .nav-in {\n  max-width: var(--maxw); margin: 0 auto; height: 64px; padding: 0 var(--gut);\n  display: flex; align-items: center; gap: 28px;\n}\n.own-expo .wordmark {\n  display: inline-flex; align-items: center; gap: 9px;\n  font-size: 18px; font-weight: 600; letter-spacing: -.4px; color: var(--ink);\n  text-decoration: none; white-space: nowrap;\n}\n.own-expo .mark {\n  display: grid; place-items: center; width: 26px; height: 26px; border-radius: var(--r-sm);\n  background: var(--ink); color: #fff;\n}\n.own-expo .mark svg { width: 17px; height: 17px; }\n.own-expo .nav-links { display: flex; align-items: center; gap: 22px; margin-left: 8px; }\n.own-expo .nav-links a {\n  font-size: 14px; font-weight: 500; color: var(--ink); text-decoration: none; white-space: nowrap;\n  transition: color .18s;\n}\n.own-expo .nav-links a:hover { color: var(--body); }\n.own-expo .nav-right { margin-left: auto; display: flex; align-items: center; gap: 14px; }\n.own-expo .nav-signin { font-size: 14px; font-weight: 500; color: var(--ink); text-decoration: none; white-space: nowrap; }\n.own-expo .nav-signin:hover { color: var(--body); }\n.own-expo .nav-burger {\n  display: none; width: 40px; height: 40px; border: 1px solid var(--hairline-strong);\n  border-radius: var(--r-md); background: var(--surface-card); color: var(--ink); cursor: pointer;\n  align-items: center; justify-content: center;\n}\n.own-expo .nav-burger svg { width: 20px; height: 20px; }\n\n/* ── hero + device mockup ────────────────────────────────────────────────── */\n.own-expo .hero { position: relative; padding: clamp(56px, 7cqi, 96px) 0 0; overflow: hidden; }\n.own-expo .hero-wash {\n  position: absolute; inset: -20% -10% auto -10%; height: 92%; z-index: 0; pointer-events: none;\n  background:\n    radial-gradient(60% 70% at 50% 6%, var(--sky-light) 0%, color-mix(in srgb, var(--sky-mid) 55%, transparent) 38%, transparent 72%),\n    radial-gradient(40% 50% at 78% 20%, color-mix(in srgb, var(--sky-light) 80%, transparent) 0%, transparent 60%);\n}\n.own-expo .hero-in { position: relative; z-index: 1; text-align: center; }\n.own-expo .hero-title {\n  font-size: clamp(38px, 5.4cqi, 64px); font-weight: 600; line-height: 1.05;\n  letter-spacing: -1.92px; color: var(--ink); margin: 20px auto 0; max-width: 17ch;\n}\n.own-expo .hero-sub {\n  font-size: 18px; font-weight: 400; line-height: 1.5; color: var(--body);\n  margin: 22px auto 0; max-width: 60ch;\n}\n.own-expo .hero-cta { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 30px; }\n.own-expo .hero-foot { font-size: 13px; color: var(--body); margin: 18px 0 0; }\n\n.own-expo .mock-stage {\n  position: relative; margin: clamp(40px, 5cqi, 64px) auto 0; max-width: 900px;\n  padding: 0 0 clamp(60px, 8cqi, 96px);\n}\n.own-expo .laptop { width: 100%; }\n.own-expo .laptop-screen {\n  border: 1px solid var(--hairline-strong); border-radius: var(--r-xl) var(--r-xl) var(--r-md) var(--r-md);\n  background: var(--surface-card); padding: 10px; box-shadow: 0 24px 60px -30px rgba(23, 23, 23, .28);\n}\n.own-expo .laptop-base {\n  height: 14px; margin: 0 auto; width: 108%; max-width: 100%;\n  background: linear-gradient(180deg, #e9e9ec, #d4d5d9);\n  border-radius: 0 0 14px 14px; box-shadow: 0 6px 12px -6px rgba(23, 23, 23, .3);\n  display: flex; justify-content: center;\n}\n.own-expo .laptop-notch { width: 96px; height: 6px; margin-top: 3px; border-radius: var(--r-pill); background: #c2c3c8; }\n\n.own-expo .dash { border-radius: var(--r-md); overflow: hidden; background: var(--canvas); border: 1px solid var(--hairline); }\n.own-expo .dash-bar {\n  display: flex; align-items: center; gap: 7px; height: 34px; padding: 0 12px;\n  background: var(--surface-strong); border-bottom: 1px solid var(--hairline);\n}\n.own-expo .dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; }\n.own-expo .dot.red { background: #f0b4b4; }\n.own-expo .dot.amber { background: #f0d6a0; }\n.own-expo .dot.green { background: #a9dcb8; }\n.own-expo .dash-name { font-size: 12px; font-weight: 600; color: var(--ink); margin-left: 8px; }\n.own-expo .dash-live {\n  margin-left: auto; display: inline-flex; align-items: center; gap: 5px;\n  font-size: 11px; font-weight: 600; color: var(--semantic-success); letter-spacing: .4px;\n}\n.own-expo .dash-live i { width: 7px; height: 7px; border-radius: 50%; background: var(--semantic-success); display: inline-block; }\n.own-expo .dash-body { display: grid; grid-template-columns: 148px 1fr; min-height: 300px; }\n.own-expo .dash-side {\n  display: flex; flex-direction: column; gap: 2px; padding: 14px 12px;\n  border-right: 1px solid var(--hairline); background: var(--canvas-soft); text-align: left;\n}\n.own-expo .ds { font-size: 12.5px; font-weight: 500; color: var(--body); padding: 7px 9px; border-radius: var(--r-sm); }\n.own-expo .ds.on { background: var(--surface-strong); color: var(--ink); font-weight: 600; }\n.own-expo .dash-main { padding: 18px; text-align: left; }\n.own-expo .kpis { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }\n.own-expo .kpi {\n  padding: 14px; border: 1px solid var(--hairline); border-radius: var(--r-md); background: var(--surface-card);\n  display: flex; flex-direction: column; gap: 3px;\n}\n.own-expo .kpi-num { font-size: 24px; font-weight: 600; letter-spacing: -.8px; color: var(--ink); line-height: 1.1; font-variant-numeric: tabular-nums; }\n.own-expo .kpi span { font-size: 11px; color: var(--body); letter-spacing: .4px; text-transform: uppercase; font-weight: 600; }\n.own-expo .dash-chart { width: 100%; height: 88px; margin-top: 16px; display: block; }\n.own-expo .dash-log { display: flex; flex-direction: column; gap: 6px; margin-top: 14px; }\n.own-expo .log-line {\n  display: flex; align-items: center; gap: 8px; font-family: var(--f-mono); font-size: 11.5px;\n  color: var(--body); padding: 7px 10px; border-radius: var(--r-sm); background: var(--canvas-soft);\n  border: 1px solid var(--hairline-soft);\n}\n.own-expo .log-dot { width: 7px; height: 7px; border-radius: 50%; flex: none; background: var(--semantic-success); }\n.own-expo .log-dot.warn { background: #f0b23f; }\n.own-expo .log-line b { color: var(--ink); font-weight: 600; }\n\n.own-expo .phone {\n  position: absolute; right: -6px; bottom: 0; width: clamp(120px, 15cqi, 168px);\n  border-radius: 26px; background: var(--ink); padding: 9px; box-shadow: 0 28px 54px -26px rgba(23, 23, 23, .5);\n}\n.own-expo .phone-notch {\n  position: absolute; top: 14px; left: 50%; transform: translateX(-50%);\n  width: 42px; height: 5px; border-radius: var(--r-pill); background: rgba(255, 255, 255, .28);\n}\n.own-expo .phone-screen {\n  border-radius: 18px; background: var(--canvas); padding: 34px 14px 16px;\n  display: flex; flex-direction: column; align-items: center; gap: 3px; min-height: 210px;\n}\n.own-expo .ph-brand { font-size: 10px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase; color: var(--body); }\n.own-expo .ph-num { font-size: 30px; font-weight: 600; letter-spacing: -1px; color: var(--ink); line-height: 1.1; font-variant-numeric: tabular-nums; }\n.own-expo .ph-cap { font-size: 10px; color: var(--body); }\n.own-expo .ph-bars { display: flex; align-items: flex-end; gap: 5px; height: 52px; margin: 14px 0 10px; }\n.own-expo .ph-bars i { width: 10px; border-radius: 3px; background: color-mix(in srgb, var(--sky-mid) 70%, var(--ink) 12%); display: block; }\n.own-expo .ph-bars i:nth-child(1) { height: 40%; }\n.own-expo .ph-bars i:nth-child(2) { height: 62%; }\n.own-expo .ph-bars i:nth-child(3) { height: 48%; }\n.own-expo .ph-bars i:nth-child(4) { height: 78%; }\n.own-expo .ph-bars i:nth-child(5) { height: 58%; }\n.own-expo .ph-bars i:nth-child(6) { height: 88%; background: var(--ink); }\n.own-expo .ph-bars i:nth-child(7) { height: 70%; }\n.own-expo .ph-note { font-size: 10.5px; font-weight: 600; color: var(--semantic-success); text-align: center; }\n\n/* ── workflow steps ──────────────────────────────────────────────────────── */\n.own-expo .steps {\n  list-style: none; margin: 44px 0 0; padding: 0;\n  display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px;\n}\n.own-expo .step {\n  padding: 20px; border: 1px solid var(--hairline-strong); border-radius: var(--r-lg);\n  background: var(--surface-card); display: flex; flex-direction: column; gap: 10px;\n  transition: box-shadow .2s, border-color .2s;\n}\n.own-expo .step:hover { box-shadow: 0 4px 12px rgba(0, 0, 0, .04); border-color: var(--hairline); }\n.own-expo .step-icon {\n  display: grid; place-items: center; width: 32px; height: 32px; border-radius: var(--r-md);\n  background: var(--surface-strong); color: var(--ink);\n}\n.own-expo .step-icon svg { width: 19px; height: 19px; }\n.own-expo .step-n { font-family: var(--f-mono); font-size: 12px; font-weight: 400; color: var(--body); }\n.own-expo .step-t { font-size: 18px; font-weight: 600; line-height: 1.4; color: var(--ink); margin: 0; }\n.own-expo .step-d { font-size: 14px; line-height: 1.5; color: var(--body); margin: 0; }\n\n/* ── dark feature band + code ────────────────────────────────────────────── */\n.own-expo .dark-band { background: var(--surface-dark); color: var(--on-dark); }\n.own-expo .tools-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 44px; align-items: start; }\n.own-expo .code-block {\n  border-radius: var(--r-lg); background: var(--surface-dark-elevated);\n  border: 1px solid rgba(255, 255, 255, .09); overflow: hidden;\n}\n.own-expo .code-bar {\n  display: flex; align-items: center; gap: 7px; height: 38px; padding: 0 14px;\n  border-bottom: 1px solid rgba(255, 255, 255, .09);\n}\n.own-expo .code-file { margin-left: 10px; font-family: var(--f-mono); font-size: 12px; color: var(--on-dark-soft); }\n.own-expo .code { margin: 0; padding: 20px; overflow-x: auto; }\n.own-expo .code code {\n  font-family: var(--f-mono); font-size: 13px; line-height: 1.5; font-weight: 400;\n  color: #e6e6ea; white-space: pre; display: block;\n}\n.own-expo .code.small code { font-size: 12.5px; }\n.own-expo .c-key { color: var(--sky-light); }\n.own-expo .c-str { color: #ffd9a0; }\n.own-expo .c-com { color: var(--on-dark-soft); }\n.own-expo .tool-cards { display: grid; gap: 12px; }\n.own-expo .card-dark {\n  padding: 24px; border-radius: var(--r-lg); background: var(--surface-dark-elevated);\n  border: 1px solid rgba(255, 255, 255, .09);\n}\n.own-expo .card-dark-t { font-size: 18px; font-weight: 600; line-height: 1.4; color: var(--on-dark); margin: 0; }\n.own-expo .card-dark-p { font-size: 14px; line-height: 1.5; color: var(--on-dark-soft); margin: 8px 0 0; }\n\n/* ── IDE mockup ──────────────────────────────────────────────────────────── */\n.own-expo .eas-in { display: grid; grid-template-columns: .85fr 1.15fr; gap: clamp(28px, 4cqi, 64px); align-items: center; }\n.own-expo .eas-copy .tlink-lg { display: inline-block; margin-top: 20px; }\n.own-expo .ide {\n  border-radius: var(--r-lg); overflow: hidden; background: var(--surface-dark);\n  border: 1px solid rgba(255, 255, 255, .1); box-shadow: 0 30px 70px -40px rgba(23, 23, 23, .6);\n}\n.own-expo .ide-bar { display: flex; align-items: center; gap: 7px; height: 40px; padding: 0 14px; border-bottom: 1px solid rgba(255, 255, 255, .09); }\n.own-expo .ide-tab {\n  font-family: var(--f-mono); font-size: 12px; color: var(--on-dark-soft);\n  padding: 5px 10px; border-radius: var(--r-sm); margin-left: 6px;\n}\n.own-expo .ide-tab.on { background: rgba(255, 255, 255, .1); color: var(--on-dark); }\n.own-expo .ide-panes { display: grid; grid-template-columns: 130px 1fr; min-height: 190px; }\n.own-expo .ide-tree { display: flex; flex-direction: column; gap: 2px; padding: 12px 10px; border-right: 1px solid rgba(255, 255, 255, .09); }\n.own-expo .it { font-family: var(--f-mono); font-size: 12px; color: var(--on-dark-soft); padding: 6px 8px; border-radius: var(--r-sm); }\n.own-expo .it.on { background: rgba(255, 255, 255, .1); color: var(--on-dark); }\n.own-expo .ide-editor { padding: 16px; overflow-x: auto; background: var(--surface-dark-elevated); }\n.own-expo .ide-editor .code { padding: 0; }\n.own-expo .ide-term { padding: 14px 16px; border-top: 1px solid rgba(255, 255, 255, .09); display: flex; flex-direction: column; gap: 5px; background: #131313; }\n.own-expo .term-line { font-family: var(--f-mono); font-size: 12.5px; color: var(--on-dark-soft); }\n.own-expo .term-line.ok { color: var(--semantic-success); }\n.own-expo .caret { display: inline-block; width: 8px; height: 14px; background: var(--sky-light); vertical-align: -2px; animation: expo-blink 1.1s steps(1) infinite; }\n.own-expo .term-line .c-key { color: var(--sky-light); }\n@keyframes expo-blink { 50% { opacity: 0; } }\n\n/* ── ecosystem tiles ─────────────────────────────────────────────────────── */\n.own-expo .eco {\n  list-style: none; margin: 44px 0 0; padding: 0;\n  display: grid; grid-template-columns: repeat(8, 1fr); gap: 16px;\n}\n.own-expo .tile {\n  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px;\n  aspect-ratio: 1 / 1; padding: 12px 8px; border: 1px solid var(--hairline);\n  border-radius: var(--r-md); background: var(--surface-card);\n  transition: box-shadow .2s, transform .2s;\n}\n.own-expo .tile:hover { box-shadow: 0 4px 12px rgba(0, 0, 0, .04); transform: translateY(-2px); }\n.own-expo .tile-glyph {\n  display: grid; place-items: center; width: 34px; height: 34px; border-radius: var(--r-sm);\n  background: var(--surface-strong); color: var(--ink);\n  font-family: var(--f-mono); font-size: 12px; font-weight: 400; letter-spacing: .5px;\n}\n.own-expo .tile-name { font-size: 12px; font-weight: 500; color: var(--body); text-align: center; }\n\n/* ── pricing ─────────────────────────────────────────────────────────────── */\n.own-expo .tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 44px; align-items: stretch; }\n.own-expo .tier {\n  position: relative; padding: 32px; border-radius: var(--r-lg);\n  background: var(--surface-card); border: 1px solid var(--hairline-strong);\n  display: flex; flex-direction: column;\n}\n.own-expo .tier.featured { background: var(--surface-dark); color: var(--on-dark); border-color: var(--surface-dark); }\n.own-expo .tier-flag {\n  position: absolute; top: -12px; left: 32px; padding: 4px 10px; border-radius: var(--r-pill);\n  background: var(--surface-strong); color: var(--ink);\n  font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase;\n}\n.own-expo .tier-name { font-size: 18px; font-weight: 600; line-height: 1.4; margin: 0; color: inherit; }\n.own-expo .tier-price { display: flex; align-items: baseline; gap: 6px; margin: 14px 0 0; }\n.own-expo .tier-price b { font-size: 36px; font-weight: 600; letter-spacing: -1.08px; line-height: 1.15; color: inherit; }\n.own-expo .tier-price span { font-size: 14px; color: var(--body); }\n.own-expo .tier.featured .tier-price span { color: var(--on-dark-soft); }\n.own-expo .tier-desc { font-size: 14px; line-height: 1.5; color: var(--body); margin: 12px 0 0; }\n.own-expo .tier.featured .tier-desc { color: var(--on-dark-soft); }\n.own-expo .tier-list { list-style: none; margin: 20px 0 28px; padding: 0; display: grid; gap: 10px; }\n.own-expo .tier-list li {\n  position: relative; padding-left: 24px; font-size: 14px; line-height: 1.5; color: var(--body);\n}\n.own-expo .tier.featured .tier-list li { color: var(--on-dark-soft); }\n.own-expo .tier-list li::before {\n  content: ''; position: absolute; left: 4px; top: 2px; width: 12px; height: 12px; transform: rotate(45deg);\n  border-right: 2px solid var(--semantic-success); border-bottom: 2px solid var(--semantic-success);\n}\n.own-expo .tier-btn { margin-top: auto; align-self: flex-start; }\n\n/* ── testimonial ─────────────────────────────────────────────────────────── */\n.own-expo .quote {\n  margin: 0; max-width: 820px; padding: 32px; border: 1px solid var(--hairline-strong);\n  border-radius: var(--r-lg); background: var(--surface-card);\n}\n.own-expo .quote-body {\n  margin: 0; font-size: clamp(20px, 2.2cqi, 28px); font-weight: 600; line-height: 1.35;\n  letter-spacing: -.84px; color: var(--ink); text-wrap: balance;\n}\n.own-expo .quote-foot { display: flex; align-items: center; gap: 14px; margin-top: 24px; }\n.own-expo .quote-avatar {\n  display: grid; place-items: center; width: 44px; height: 44px; border-radius: var(--r-pill);\n  background: var(--surface-strong); color: var(--ink); font-size: 14px; font-weight: 600; letter-spacing: .5px;\n}\n.own-expo .quote-meta { display: flex; flex-direction: column; }\n.own-expo .quote-meta b { font-size: 15px; font-weight: 600; color: var(--ink); }\n.own-expo .quote-meta span { font-size: 13px; color: var(--body); }\n\n/* ── CTA band ────────────────────────────────────────────────────────────── */\n.own-expo .cta-band { padding: var(--section) 0; scroll-margin-top: 84px; }\n.own-expo .cta-in {\n  text-align: center; border: 1px solid var(--hairline);\n  border-radius: var(--r-xxl); padding: clamp(40px, 6cqi, 72px) var(--gut);\n  background:\n    radial-gradient(80% 120% at 50% 0%, var(--sky-light) 0%, transparent 62%), var(--surface-card);\n}\n.own-expo .cta-title { font-size: clamp(28px, 3.2cqi, 44px); font-weight: 600; line-height: 1.15; letter-spacing: -1.08px; color: var(--ink); margin: 0; }\n.own-expo .cta-sub { font-size: 16px; color: var(--body); margin: 14px 0 0; }\n.own-expo .cta-actions { display: flex; gap: 18px; justify-content: center; align-items: center; flex-wrap: wrap; margin-top: 28px; }\n\n/* ── footer ──────────────────────────────────────────────────────────────── */\n.own-expo .foot { border-top: 1px solid var(--hairline); background: var(--canvas); padding: 64px 0 40px; }\n.own-expo .foot-top { display: flex; flex-direction: column; gap: 10px; margin-bottom: 40px; }\n.own-expo .foot-mark { font-size: 20px; }\n.own-expo .foot-tag { font-size: 14px; color: var(--body); margin: 0; }\n.own-expo .foot-cols { display: grid; grid-template-columns: repeat(5, 1fr); gap: 24px; }\n.own-expo .foot-col { display: flex; flex-direction: column; gap: 10px; }\n.own-expo .foot-h { font-size: 11px; font-weight: 600; letter-spacing: .88px; text-transform: uppercase; color: var(--ink); margin: 0 0 2px; }\n.own-expo .foot-col a { font-size: 14px; color: var(--body); text-decoration: none; }\n.own-expo .foot-col a:hover { color: var(--ink); }\n.own-expo .foot-bar {\n  display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap;\n  margin-top: 48px; padding-top: 24px; border-top: 1px solid var(--hairline);\n  font-size: 13px; color: var(--body);\n}\n.own-expo .foot-bar-links { display: inline-flex; gap: 18px; }\n\n/* ── motion ──────────────────────────────────────────────────────────────── */\n@keyframes expo-rise { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: none; } }\n.own-expo .hero-in > * { animation: expo-rise .7s var(--ease) both; }\n.own-expo .hero-in > :nth-child(2) { animation-delay: .06s; }\n.own-expo .hero-in > :nth-child(3) { animation-delay: .12s; }\n.own-expo .hero-in > :nth-child(4) { animation-delay: .18s; }\n.own-expo .hero-in > :nth-child(5) { animation-delay: .24s; }\n.own-expo .hero-in > :nth-child(6) { animation-delay: .3s; }\n\n/* ── responsive ──────────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-expo .steps { grid-template-columns: repeat(2, 1fr); }\n  .own-expo .eco { grid-template-columns: repeat(4, 1fr); }\n  .own-expo .tools-grid { grid-template-columns: 1fr; }\n  .own-expo .eas-in { grid-template-columns: 1fr; }\n  .own-expo .tiers { grid-template-columns: 1fr; gap: 32px; }\n  .own-expo .foot-cols { grid-template-columns: repeat(3, 1fr); gap: 28px; }\n}\n\n@container frame (max-width: 760px) {\n  .own-expo .nav-links { display: none; }\n  .own-expo .nav-signin { display: none; }\n  .own-expo .nav-burger { display: inline-flex; }\n  .own-expo .nav.menu-open .nav-links {\n    display: flex; flex-direction: column; align-items: flex-start; gap: 4px;\n    position: absolute; left: 0; right: 0; top: 100%; margin: 0; padding: 14px var(--gut) 10px;\n    background: var(--canvas); border-bottom: 1px solid var(--hairline);\n  }\n  .own-expo .nav.menu-open .nav-links a { padding: 8px 0; font-size: 15px; }\n  .own-expo .hero-wash { inset: -14% -10% auto -10%; height: 80%; }\n  .own-expo .dash-body { grid-template-columns: 1fr; min-height: 0; }\n  .own-expo .dash-side { flex-direction: row; gap: 4px; overflow-x: auto; border-right: 0; border-bottom: 1px solid var(--hairline); padding: 10px; }\n  .own-expo .ds { white-space: nowrap; }\n  .own-expo .kpis { grid-template-columns: 1fr; }\n  .own-expo .phone { right: 0; width: 120px; }\n  .own-expo .ph-bars { height: 40px; }\n  .own-expo .eco { grid-template-columns: repeat(3, 1fr); }\n  .own-expo .foot-cols { grid-template-columns: repeat(2, 1fr); }\n  .own-expo .foot-bar { flex-direction: column; align-items: flex-start; gap: 10px; }\n}\n\n@container frame (max-width: 430px) {\n  .own-expo .steps { grid-template-columns: 1fr; }\n  .own-expo .eco { grid-template-columns: repeat(2, 1fr); }\n  .own-expo .nav-right { gap: 8px; }\n  .own-expo .btn { padding: 10px 16px; }\n  .own-expo .hero-cta { flex-direction: column; align-items: stretch; }\n  .own-expo .hero-cta .btn { width: 100%; }\n  .own-expo .cta-actions { flex-direction: column; align-items: stretch; }\n  .own-expo .cta-actions .btn { width: 100%; }\n  .own-expo .quote { padding: 24px; }\n  .own-expo .tier, .own-expo .card-dark { padding: 22px; }\n  .own-expo .foot-cols { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-expo *,\n  .own-expo *::before,\n  .own-expo *::after {\n    animation-duration: .001ms !important;\n    animation-iteration-count: 1 !important;\n    transition-duration: .001ms !important;\n  }\n  .own-expo .caret { animation: none; }\n}\n"};
/* ══ NORTHWIND (Expo design language) — own showcase layout behaviour ══════
   Registers window.OWN_LAYOUTS['expo'].init(root). Everything is queried inside
   `root`; `init` returns a cleanup function so unmounting leaves no listener,
   rAF, observer or timer behind. The page is largely static — the JS only fills
   the mock dashboard log, animates the KPI counters, and toggles the mobile nav. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  /* Fictional operations events — no real Expo product surface or brand copy. */
  var LOG = [
    { t: '14:02', msg: 'APAC · throughput +6.4% vs plan', warn: false },
    { t: '13:58', msg: 'EU-West · queue depth normalized', warn: true },
    { t: '13:41', msg: 'US-East · alert resolved in 3m 12s', warn: false },
    { t: '13:30', msg: 'LATAM · cost per unit $0.021', warn: false }
  ];

  OWN['expo'] = {
    init: function (root) {
      if (!root) return function () {};

      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var rafs = [];
      var timeouts = [];
      var observers = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function later(fn, ms) { var id = window.setTimeout(fn, ms); timeouts.push(id); return id; }
      function $(sel) { return root.querySelector(sel); }
      function $$(sel) { return Array.prototype.slice.call(root.querySelectorAll(sel)); }

      /* ── mock dashboard log ──────────────────────────────────────────── */
      var logEl = $('#expoLog');
      if (logEl) {
        logEl.innerHTML = LOG.map(function (row) {
          return '<span class="log-line"><i class="log-dot' + (row.warn ? ' warn' : '') + '"></i>'
            + '<b>' + esc(row.t) + '</b><span>' + esc(row.msg) + '</span></span>';
        }).join('');
      }

      /* ── KPI count-up (respects reduced motion) ──────────────────────── */
      function countTo(el) {
        var to = Number(el.getAttribute('data-count') || 0);
        var suffix = el.getAttribute('data-suffix') || '';
        var fmt = el.getAttribute('data-fmt');
        function render(v) {
          if (fmt === 'k') return Math.round(v).toLocaleString('en-US');
          return String(Math.round(v)) + suffix;
        }
        if (reduced) { el.textContent = render(to); return; }
        var t0 = performance.now();
        function step(t) {
          if (disposed) return;
          var k = Math.min(1, (t - t0) / 900);
          var e = 1 - Math.pow(1 - k, 4);
          el.textContent = render(to * e);
          if (k < 1) raf(step);
        }
        raf(step);
      }
      $$('.kpi-num').forEach(countTo);

      /* ── mobile nav toggle ───────────────────────────────────────────── */
      var nav = $('#expoNav');
      var burger = $('[data-burger]');
      function closeMenu() {
        if (!nav) return;
        nav.classList.remove('menu-open');
        if (burger) burger.setAttribute('aria-expanded', 'false');
      }
      on(burger, 'click', function () {
        if (!nav) return;
        var open = nav.classList.toggle('menu-open');
        burger.setAttribute('aria-expanded', open ? 'true' : 'false');
      });
      on(document, 'keydown', function (e) { if (e.key === 'Escape') closeMenu(); });

      /* ── in-layout smooth scroll for same-page links ─────────────────── */
      $$('a[href^="#"]').forEach(function (a) {
        on(a, 'click', function (e) {
          var href = a.getAttribute('href');
          if (!href || href.length < 2) return;
          var target = root.querySelector(href);
          if (!target) return;
          e.preventDefault();
          closeMenu();
          target.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
          try { history.replaceState(null, '', href); } catch (err) { /* ignore */ }
        });
      });

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        timeouts.forEach(function (id) { clearTimeout(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
        closeMenu();
      };
    }
  };
})();
